import type { FailureKind } from '@pjgen/shared';
import type { RateLimitInfo } from './ndjson.js';

export interface SessionSpec {
  cwd: string;
  prompt: string;
  /** UUID generated by us; passed as --session-id (new) or --resume (existing). */
  sessionId: string;
  resume: boolean;
  forkSession?: boolean;
  model: string;
  fallbackModel?: string;
  /** 'none' = no tools; 'default' = full autonomy; string[] = named allowlist (e.g. ['WebSearch','WebFetch']). */
  tools: 'none' | 'default' | string[];
  jsonSchema?: object;
  appendSystemPrompt?: string;
  maxBudgetUsd?: number;
  /** Self-enforced caps (the CLI no longer has --max-turns). */
  maxTurns: number;
  timeoutMs: number;
}

export interface Failure {
  kind: FailureKind;
  message: string;
  /** Epoch ms at which the usage limit is expected to reset (usage_limit only). */
  resetAt?: number;
  matchedPattern?: string;
}

export interface LogEntryInput {
  kind: 'stdout_json' | 'stderr' | 'meta';
  line: string;
  display: string;
}

export interface RunHooks {
  onLog?(entry: LogEntryInput): void;
  onPid?(pid: number): void;
}

export interface RunUsage {
  inputTokens: number;
  outputTokens: number;
  cacheCreationTokens: number;
  cacheReadTokens: number;
}

export const ZERO_USAGE: RunUsage = { inputTokens: 0, outputTokens: 0, cacheCreationTokens: 0, cacheReadTokens: 0 };

export interface RunResult {
  outcome: 'success' | 'failure';
  sessionId: string;
  resultText: string;
  structured?: unknown;
  numTurns: number;
  costUsd: number;
  usage: RunUsage;
  /** Latest rate_limit_event of the stream (emitted on every request) — powers the 5h-window gauge. */
  rateLimitInfo?: RateLimitInfo;
  durationMs: number;
  failure?: Failure;
}

export interface RunHandle {
  readonly pid: number | null;
  readonly result: Promise<RunResult>;
  cancel(reason: 'canceled' | 'timeout'): void;
}

export type RunnerFn = (spec: SessionSpec, hooks?: RunHooks) => RunHandle;
